import{_ as a,c as o,o as t,aj as r}from"./chunks/framework.Id7s26SP.js";const b=JSON.parse('{"title":"Interface: AgentSessionAttachments","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionAttachments.md","filePath":"reference/js-bao-wss-client/api/interfaces/AgentSessionAttachments.md"}'),s={name:"reference/js-bao-wss-client/api/interfaces/AgentSessionAttachments.md"};function n(d,e,i,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / AgentSessionAttachments</p><h1 id="interface-agentsessionattachments" tabindex="-1">Interface: AgentSessionAttachments <a class="header-anchor" href="#interface-agentsessionattachments" aria-label="Permalink to “Interface: AgentSessionAttachments”">​</a></h1><p>A session&#39;s files: upload them (queued and retried, surviving the view&#39;s close), follow and control the queue, and read any file of the session. From <code>view.attachments</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="cancel" tabindex="-1">cancel() <a class="header-anchor" href="#cancel" aria-label="Permalink to “cancel()”">​</a></h3><blockquote><p><strong>cancel</strong>(<code>blobId</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Drop an upload from the queue with its local bytes, aborting a transfer in flight. Never deletes anything on the server.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blobid" tabindex="-1">blobId <a class="header-anchor" href="#blobid" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The upload&#39;s blob id</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p>false when the id is not queued (completed, cancelled or unknown)</p><hr><h3 id="pause" tabindex="-1">pause() <a class="header-anchor" href="#pause" aria-label="Permalink to “pause()”">​</a></h3><blockquote><p><strong>pause</strong>(<code>blobId</code>): <code>boolean</code></p></blockquote><p>Pause a pending or uploading upload, aborting a transfer in flight.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blobid-1" tabindex="-1">blobId <a class="header-anchor" href="#blobid-1" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The upload&#39;s blob id</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>false for an unknown id or an upload that is not pending or uploading</p><hr><h3 id="read" tabindex="-1">read() <a class="header-anchor" href="#read" aria-label="Permalink to “read()”">​</a></h3><blockquote><p><strong>read</strong>(<code>blobId</code>, <code>options?</code>): <code>Promise</code>&lt;<code>string</code> | <code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>Blob</code>&gt;</p></blockquote><p>Read a file of the session: the local copy when this client holds one (an upload it made, or an earlier read), else a download through the session, kept for next time. Rejects with the server&#39;s <code>code</code> (<code>AGENT_SESSION_ATTACHMENT_NOT_FOUND</code> for an id the session does not hold).</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blobid-2" tabindex="-1">blobId <a class="header-anchor" href="#blobid-2" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The file&#39;s blob id</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./BlobReadOptions.html"><code>BlobReadOptions</code></a></p><p>The return format, a forced download, and the disposition</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code> | <code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>Blob</code>&gt;</p><hr><h3 id="resume" tabindex="-1">resume() <a class="header-anchor" href="#resume" aria-label="Permalink to “resume()”">​</a></h3><blockquote><p><strong>resume</strong>(<code>blobId</code>): <code>boolean</code></p></blockquote><p>Make a paused or failed upload pending at once; for a failed one this is the retry.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blobid-3" tabindex="-1">blobId <a class="header-anchor" href="#blobid-3" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The upload&#39;s blob id</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>false for an unknown id or an upload that is not paused or failed</p><hr><h3 id="upload" tabindex="-1">upload() <a class="header-anchor" href="#upload" aria-label="Permalink to “upload()”">​</a></h3><blockquote><p><strong>upload</strong>(<code>source</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./AgentSessionAttachment.html"><code>AgentSessionAttachment</code></a>&gt;</p></blockquote><p>Upload a file to the session. The bytes are stored locally and one attempt is made at once; resolves once it landed or, on a retryable failure or while offline, once it is queued for retry. A refusal (<code>AGENT_SESSION_PARTICIPANT_ONLY</code>, <code>AGENT_SESSION_NOT_FOUND</code>, a size or integrity error) rejects with the server&#39;s <code>code</code>, and the upload stays in <code>uploads()</code> as <code>failed</code> with its bytes.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="source" tabindex="-1">source <a class="header-anchor" href="#source" aria-label="Permalink to “source”">​</a></h5><p><code>ArrayBuffer</code> | <code>Uint8Array</code>&lt;<code>ArrayBufferLike</code>&gt; | <code>File</code> | <code>Blob</code></p><p>The file&#39;s bytes</p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./AgentSessionAttachmentUploadOptions.html"><code>AgentSessionAttachmentUploadOptions</code></a></p><p>Filename, media type and disposition</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionAttachment.html"><code>AgentSessionAttachment</code></a>&gt;</p><hr><h3 id="uploads" tabindex="-1">uploads() <a class="header-anchor" href="#uploads" aria-label="Permalink to “uploads()”">​</a></h3><blockquote><p><strong>uploads</strong>(): <a href="./AgentSessionUploadStatus.html"><code>AgentSessionUploadStatus</code></a>[]</p></blockquote><p>The session&#39;s uploads that have not completed, most recently changed first.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./AgentSessionUploadStatus.html"><code>AgentSessionUploadStatus</code></a>[]</p><hr><h3 id="waituntiluploaded" tabindex="-1">waitUntilUploaded() <a class="header-anchor" href="#waituntiluploaded" aria-label="Permalink to “waitUntilUploaded()”">​</a></h3><blockquote><p><strong>waitUntilUploaded</strong>(<code>blobId</code>): <code>Promise</code>&lt;<a href="./AgentSessionAttachment.html"><code>AgentSessionAttachment</code></a>&gt;</p></blockquote><p>Resolve once the upload completes, or at once for one that completed in this process. Rejects with the upload&#39;s error once it fails, and with an <code>AgentSessionUploadWaitError</code> when it is cancelled, when the signed-in identity changes, or for an id this client never uploaded.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blobid-4" tabindex="-1">blobId <a class="header-anchor" href="#blobid-4" aria-label="Permalink to “blobId”">​</a></h5><p><code>string</code></p><p>The upload&#39;s blob id</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AgentSessionAttachment.html"><code>AgentSessionAttachment</code></a>&gt;</p>',80)])])}const u=a(s,[["render",n]]);export{b as __pageData,u as default};
